    public static View hstack(View... children) {
        return new ComponentNode(Constants.HSTACK, null, Arrays.asList(children));
    }

    /** Create a HStack with constructor properties (structural/layout — never chainable). */
    public static View hstack(Align alignment, Justify justification, float spacing, View... children) {
        ComponentNode node = new ComponentNode(Constants.HSTACK, null, Arrays.asList(children));
        node.setConstructorProp(Constants.ALIGNMENT, alignment.wire);
        node.setConstructorProp(Constants.JUSTIFICATION, justification.wire);
        node.setConstructorProp(Constants.SPACING, spacing);
        return node;
    }

    /** Create a Image. */
    public static View image() {
        return new ComponentNode(Constants.IMAGE, null, java.util.Collections.emptyList());
    }

